CREATE OR REPLACE FUNCTION public.sync_reservation_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_count int;
begin
  if tg_op = 'DELETE' then
    delete from public.inventory_allocations where reservation_id=old.id;
    return old;
  end if;
  if tg_op = 'UPDATE' then
    delete from public.inventory_allocations where reservation_id=new.id;
  end if;
  if new.status in ('pending','confirmed') then
    select count(*) into v_count from public.unit_resource_requirements where unit_id=new.unit_id;
    if v_count=0 then raise exception 'Missing inventory resource mapping'; end if;
    insert into public.inventory_allocations(resource_id,starts_at,ends_at,allocation_kind,unit_id,reservation_id)
    select resource_id, (new.checkin::timestamp at time zone 'UTC'), (new.checkout::timestamp at time zone 'UTC'), 'reservation', new.unit_id,new.id
    from public.unit_resource_requirements where unit_id=new.unit_id order by resource_id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_inventory_mapping_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_unit uuid;
begin
 v_unit:=case when tg_op='DELETE' then old.unit_id else new.unit_id end;
 if exists(select 1 from public.inventory_allocations where unit_id=v_unit) then
  raise exception 'Cannot change inventory mapping while allocations exist for unit';
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.owner_property_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.published is distinct from old.published then
    raise exception 'Publication status is controlled by moderation pipeline' using errcode='42501';
  end if;
  new.owner_revision=old.owner_revision+1;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_unit_block_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_count int;
begin
 if tg_op='DELETE' then
  delete from public.inventory_allocations where block_id=old.id;
  return old;
 end if;
 if tg_op='UPDATE' then
  delete from public.inventory_allocations where block_id=new.id;
 end if;
 select count(*) into v_count from public.unit_resource_requirements where unit_id=new.unit_id;
 if v_count=0 then raise exception 'Missing inventory resource mapping for block'; end if;
 insert into public.inventory_allocations(resource_id,starts_at,ends_at,allocation_kind,unit_id,block_id)
 select resource_id,(new.starts_on::timestamp at time zone 'UTC'),(new.ends_on::timestamp at time zone 'UTC'),'block',new.unit_id,new.id
 from public.unit_resource_requirements where unit_id=new.unit_id order by resource_id;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.submit_stepan_booking(p_checkin date, p_checkout date, p_guests integer, p_name text, p_phone text, p_email text DEFAULT NULL::text, p_comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_request uuid;v_unit uuid;v_phone text;
BEGIN
 IF p_checkin IS NULL OR p_checkout IS NULL OR p_checkin < CURRENT_DATE OR p_checkout<=p_checkin OR p_checkout>p_checkin+60 OR p_guests NOT BETWEEN 1 AND 8 THEN RAISE EXCEPTION 'invalid_booking_dates_or_guests'; END IF;
 IF char_length(trim(coalesce(p_name,''))) NOT BETWEEN 2 AND 120 OR char_length(trim(coalesce(p_phone,''))) NOT BETWEEN 7 AND 32 OR char_length(coalesce(p_email,''))>200 OR char_length(coalesce(p_comment,''))>1000 THEN RAISE EXCEPTION 'invalid_booking_contact'; END IF;
 v_phone:=trim(p_phone);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_phone));
 IF (SELECT count(*) FROM public.booking_guest_contacts c WHERE c.phone=v_phone AND c.created_at>now()-interval '24 hours')>=3 THEN RAISE EXCEPTION 'too_many_requests'; END IF;
 IF (SELECT count(*) FROM public.booking_requests r WHERE r.property_id='4372d741-eab4-4c42-9ddc-88f78368f9b6'::uuid AND r.created_at>now()-interval '1 hour')>=50 THEN RAISE EXCEPTION 'temporarily_unavailable'; END IF;
 SELECT id INTO v_unit FROM public.physical_units WHERE property_id='4372d741-eab4-4c42-9ddc-88f78368f9b6'::uuid AND active=true LIMIT 1;
 IF v_unit IS NULL THEN RAISE EXCEPTION 'booking_unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM public.unit_blocks WHERE unit_id=v_unit AND starts_on<p_checkout AND ends_on>p_checkin)
 OR EXISTS(SELECT 1 FROM public.reservations WHERE unit_id=v_unit AND status IN ('pending','confirmed') AND checkin<p_checkout AND checkout>p_checkin) THEN RAISE EXCEPTION 'dates_unavailable'; END IF;
 INSERT INTO public.booking_requests(property_id,unit_id,checkin,checkout,guests,status,source)
 VALUES ('4372d741-eab4-4c42-9ddc-88f78368f9b6'::uuid,v_unit,p_checkin,p_checkout,p_guests,'new','stepan-unified-widget') RETURNING id INTO v_request;
 INSERT INTO public.booking_guest_contacts(request_id,guest_name,phone,email,guest_comment) VALUES(v_request,trim(p_name),v_phone,nullif(trim(coalesce(p_email,'')),''),nullif(trim(coalesce(p_comment,'')),''));
 RETURN v_request;
END $function$
